INSERT INTO public.user_profiles ("demoSeed", _id, _owner, "userId", "name", "username", "bio", "career", "profileVisibility", "contactPermission", "activityVisibility", "notificationsEnabled", "mutedNotifications", "updatedAt", "avatarIcon") VALUES ('demo-2026-11', '2eff1035-b006-5645-af6c-9f7e954da1af', (SELECT id FROM auth.users WHERE email='prueba@uninorte.edu.co'), (SELECT id FROM auth.users WHERE email='prueba@uninorte.edu.co'), 'Usuario Prueba', 'usuario.prueba', 'Diseño de interfaces y contenido visual. Me gusta sumar a proyectos con impacto en el campus.', 'Ingeniería de Sistemas', 'public', 'everyone', 'everyone', true, '[]', '2026-11-09T23:00:00.000Z', '');
INSERT INTO public.user_profiles ("demoSeed", _id, _owner, "userId", "name", "username", "bio", "career", "profileVisibility", "contactPermission", "activityVisibility", "notificationsEnabled", "mutedNotifications", "updatedAt", "avatarIcon") VALUES ('demo-2026-11', '4f6fc57e-98d2-52ed-86b1-15f0f9adcfc4', (SELECT id FROM auth.users WHERE email='prueba.creador@uninorte.edu.co'), (SELECT id FROM auth.users WHERE email='prueba.creador@uninorte.edu.co'), 'Camila Rojas', 'camirojas', 'Creo y lidero proyectos de innovación universitaria. Emprendimiento, cultura y tecnología.', 'Ingeniería Industrial', 'public', 'everyone', 'everyone', true, '[]', '2026-11-09T23:00:00.000Z', '');
INSERT INTO public.user_profiles ("demoSeed", _id, _owner, "userId", "name", "username", "bio", "career", "profileVisibility", "contactPermission", "activityVisibility", "notificationsEnabled", "mutedNotifications", "updatedAt", "avatarIcon") VALUES ('demo-2026-11', 'b2fd98f0-67dc-5451-847c-4ca1064ca3c5', (SELECT id FROM auth.users WHERE email='prueba.integrante@uninorte.edu.co'), (SELECT id FROM auth.users WHERE email='prueba.integrante@uninorte.edu.co'), 'Mateo Díaz', 'mateo.dev', 'Desarrollo móvil y backend. Siempre buscando con quién construir la próxima idea.', 'Ingeniería de Sistemas', 'public', 'everyone', 'everyone', true, '[]', '2026-11-09T23:00:00.000Z', '');
INSERT INTO public.user_profiles ("demoSeed", _id, _owner, "userId", "name", "username", "bio", "career", "profileVisibility", "contactPermission", "activityVisibility", "notificationsEnabled", "mutedNotifications", "updatedAt", "avatarIcon") VALUES ('demo-2026-11', '44d615db-c539-5b75-b35b-53614199e995', (SELECT id FROM auth.users WHERE email='prueba.externo@uninorte.edu.co'), (SELECT id FROM auth.users WHERE email='prueba.externo@uninorte.edu.co'), 'Sofía Herrera', 'sofi.herrera', 'Música y gestión cultural. Exploro proyectos para participar.', 'Música', 'public', 'everyone', 'everyone', true, '[]', '2026-11-09T23:00:00.000Z', '');
INSERT INTO public.projects ("demoSeed", _id, _owner, "name", "description", "categories", "canApply", "teamRoles", "acceptedRoleCounts", "duration", "audience", "isDraft", "acceptedMembersCount", "createdBy", "createdByName", "createdAt", "teamDeadline", "objectives", "stage") VALUES ('demo-2026-11', '22627c4b-33ed-58d1-9c2f-c438c62a25e1', (SELECT id FROM auth.users WHERE email='prueba.creador@uninorte.edu.co'), 'INSTAGRAM', 'INSTAGRAM es una red social universitaria para compartir fotografía y contenido del campus. Cada estudiante publica fotos de sus proyectos, eventos y clases; las agrupaciones crean historias temporales de sus actividades y la comunidad se comunica por comentarios y mensajes directos. Busca que lo que pasa en la universidad se vea y se comparta en un solo lugar, con moderación pensada para un entorno académico.', '["Tecnología"]'::jsonb, true, '{"Desarrollador/a": 2, "Diseñador/a": 1, "Comunicador/a": 1}'::jsonb, '{"Desarrollador/a": 1, "Diseñador/a": 1}'::jsonb, 'Meses', 'Toda la comunidad', false, 2, (SELECT id FROM auth.users WHERE email='prueba.creador@uninorte.edu.co'), 'Camila Rojas', '2026-09-08T14:15:00.000Z', '2026-12-05', '["Publicar fotos y carruseles con descripción, etiquetas de lugar y mención de agrupaciones.", "Historias de 24 horas para eventos en vivo del campus.", "Mensajes directos y comentarios con herramientas de moderación y reporte.", "Lanzar un piloto con 200 estudiantes antes de terminar el semestre."]'::jsonb, 'Desarrollo · MVP en pruebas internas');
INSERT INTO public.projects ("demoSeed", _id, _owner, "name", "description", "categories", "canApply", "teamRoles", "acceptedRoleCounts", "duration", "audience", "isDraft", "acceptedMembersCount", "createdBy", "createdByName", "createdAt", "teamDeadline", "objectives", "stage") VALUES ('demo-2026-11', '93ece470-dac1-5f40-9739-c0f1eb1cb54a', (SELECT id FROM auth.users WHERE email='prueba.creador@uninorte.edu.co'), 'CHISPA', 'CHISPA conecta las agrupaciones culturales del Caribe colombiano con su público. Reúne en una agenda los eventos de cumbia, bullerengue, millo y danza; muestra en un mapa dónde se presentan las agrupaciones y les da un perfil con su historia, repertorio y próximas fechas. El objetivo es visibilizar el folclor de la región y facilitar que más personas lleguen a sus presentaciones, especialmente en temporada de Carnaval.', '["Arte y cultura"]'::jsonb, true, '{"Desarrollador/a": 1, "Investigador/a": 1, "Comunicador/a": 2}'::jsonb, '{"Comunicador/a": 1}'::jsonb, 'Meses', 'Toda la comunidad', false, 1, (SELECT id FROM auth.users WHERE email='prueba.creador@uninorte.edu.co'), 'Camila Rojas', '2026-09-22T21:40:00.000Z', '2026-12-15', '["Agenda cultural con filtros por municipio, género musical y fecha.", "Perfiles de agrupaciones con historia, integrantes y repertorio.", "Mapa de presentaciones en Barranquilla, Soledad, Puerto Colombia y Malambo.", "Registrar al menos 30 agrupaciones antes del Carnaval 2027."]'::jsonb, 'Convocatoria abierta · diseño de la agenda');
INSERT INTO public.projects ("demoSeed", _id, _owner, "name", "description", "categories", "canApply", "teamRoles", "acceptedRoleCounts", "duration", "audience", "isDraft", "acceptedMembersCount", "createdBy", "createdByName", "createdAt", "teamDeadline", "objectives", "stage") VALUES ('demo-2026-11', '11d539e7-6fa5-555b-91d8-7e9d2b9d9d2d', (SELECT id FROM auth.users WHERE email='prueba.creador@uninorte.edu.co'), 'POLAR CRAVING', 'POLAR CRAVING es una marca de postres fríos con sabores del Caribe: paletas de frutas como corozo, mango biche y tamarindo, y helados artesanales servidos en la universidad. El proyecto desarrolla la identidad visual, el empaque, el catálogo digital y un sistema de pedidos para un punto de venta en el campus, con un piloto de ventas para validar precios y sabores.', '["Emprendimiento"]'::jsonb, true, '{"Diseñador/a": 1, "Comunicador/a": 1, "Líder de proyecto": 1}'::jsonb, '{"Diseñador/a": 1, "Comunicador/a": 1}'::jsonb, 'Semanas', 'Toda la comunidad', false, 2, (SELECT id FROM auth.users WHERE email='prueba.creador@uninorte.edu.co'), 'Camila Rojas', '2026-10-01T16:05:00.000Z', '2026-11-28', '["Definir la identidad visual: logo, paleta fría y empaques reciclables.", "Catálogo digital con 8 sabores y precios por presentación.", "Pedidos anticipados desde la app con recogida en el punto del campus.", "Vender 300 unidades en el piloto de dos semanas."]'::jsonb, 'Prototipo de marca · piloto de ventas');
INSERT INTO public.projects ("demoSeed", _id, _owner, "name", "description", "categories", "canApply", "teamRoles", "acceptedRoleCounts", "duration", "audience", "isDraft", "acceptedMembersCount", "createdBy", "createdByName", "createdAt", "teamDeadline", "objectives", "stage") VALUES ('demo-2026-11', '37319340-6fc9-57a8-bf49-2ab69311af7a', (SELECT id FROM auth.users WHERE email='prueba.creador@uninorte.edu.co'), 'ARTFEST', 'ARTFEST organiza y promociona festivales artísticos universitarios. Abre la convocatoria de artistas (música, danza, teatro y artes visuales), arma el cronograma de escenarios, coordina voluntarios y gestiona la entrada al evento. La primera edición se planea para el cierre del semestre en la plaza central de la universidad.', '["Arte y cultura"]'::jsonb, true, '{"Comunicador/a": 1, "Diseñador/a": 1, "Productor/a de eventos": 1}'::jsonb, '{}'::jsonb, 'Meses', 'Toda la comunidad', false, 0, (SELECT id FROM auth.users WHERE email='prueba.creador@uninorte.edu.co'), 'Camila Rojas', '2026-10-20T19:30:00.000Z', '2026-12-10', '["Recibir y seleccionar propuestas de al menos 25 artistas.", "Publicar el cronograma por escenarios y franjas horarias.", "Coordinar 40 voluntarios con turnos y funciones claras.", "Gestionar inscripciones gratuitas con cupos por actividad."]'::jsonb, 'Planeación · convocatoria de artistas');
INSERT INTO public.projects ("demoSeed", _id, _owner, "name", "description", "categories", "canApply", "teamRoles", "acceptedRoleCounts", "duration", "audience", "isDraft", "acceptedMembersCount", "createdBy", "createdByName", "createdAt", "teamDeadline", "objectives", "stage") VALUES ('demo-2026-11', '86f2cdb0-ed8b-5b8c-892a-eccdc348cf20', (SELECT id FROM auth.users WHERE email='prueba.creador@uninorte.edu.co'), 'DUO', 'DUO conecta a dos personas con habilidades complementarias para desarrollar una idea en pareja: quien tiene la idea encuentra a quien sabe construirla. Cada persona describe sus habilidades e intereses, DUO sugiere compañeros compatibles y la pareja trabaja con un tablero compartido de tareas y acuerdos. El MVP ya se entregó y se probó con estudiantes de dos facultades.', '["Educación"]'::jsonb, false, '{"Desarrollador/a": 1}'::jsonb, '{"Desarrollador/a": 1}'::jsonb, 'Semanas', 'Toda la comunidad', false, 1, (SELECT id FROM auth.users WHERE email='prueba.creador@uninorte.edu.co'), 'Camila Rojas', '2026-08-25T13:50:00.000Z', '2026-09-30', '["Emparejar estudiantes por habilidades complementarias e intereses.", "Tablero compartido de tareas y acuerdos para cada pareja.", "Probar el MVP con 20 parejas de dos facultades."]'::jsonb, 'Completado · MVP entregado');
INSERT INTO public.project_tasks ("demoSeed", _id, _owner, "projectId", "title", "description", "requiredCount", "acceptedCount", "deadline", "status", "visibility") VALUES ('demo-2026-11', 'a354fca6-bcaa-5427-a2fc-d7d104253cd5', (SELECT id FROM auth.users WHERE email='prueba.creador@uninorte.edu.co'), '22627c4b-33ed-58d1-9c2f-c438c62a25e1', 'Diseñar el feed de publicaciones', 'Pantallas del feed, detalle de foto y perfil siguiendo el sistema visual.', 1, 1, '2026-11-20', 'in_progress', 'public');
